# Create dummy classes to mimic interfaces, for testing purposes

class Patient:
    def __init__(self, age, conditions, severities):
        self.age = age
        self._conditions = conditions
        self._severities = severities

    def get_total_conditions(self):
        return len(self._conditions)

    def get_average_severity(self):
        return sum(self._severities)/len(self._severities) if self._severities else 0.0

class Hospital:
    def __init__(self, patients, records):
        # patients: dict of patient_id: Patient
        # records: dict of patient_id: list of record dicts
        self.patients = patients
        self.records = records

    def get_patient(self, patient_id):
        return self.patients[patient_id]

    def get_recent_records(self, patient_id, days):
        # Ignore days, just return for simplicity all records
        return self.records.get(patient_id, [])

def has_abnormal_vitals(records):
    # For testing we define any record with 'abnormal':True as abnormal
    return any(r.get('abnormal', False) for r in records)

def patient_risk_score(hospital, patient_id):
    '''
    Create a function called patient_risk_score that takes a Hospital object and patient_id. Calculate risk score using formula: (patient.age / 100 * 30) + (patient.get_total_conditions() * 5 * 25/100) + (patient.get_average_severity() * 10 * 25/100) + (20 if recent records have abnormal vitals else 0). Use hospital.get_patient(patient_id) and hospital.get_recent_records(patient_id, 90). Returns: float between 0.0 and 100.0.
    '''
    patient = hospital.get_patient(patient_id)
    age_score = (patient.age / 100) * 30
    conditions_score = (patient.get_total_conditions() * 5) * (25/100)
    severity_score = (patient.get_average_severity() * 10) * (25/100)
    records = hospital.get_recent_records(patient_id, 90)
    abnormal_score = 20 if has_abnormal_vitals(records) else 0
    risk = age_score + conditions_score + severity_score + abnormal_score
    return min(max(risk, 0.0), 100.0)

