import hashlib
import numpy
import numpy as np
import string
from typing import *
from collections import *


def calculate_simple_gpa(university, student_id):
    '''
    Calculate the GPA for a student given: university (University object), student_id (str).
    GPA is the sum over all courses of (grade_points * course_credits) divided by total credits.
    Returns GPA as float (0.0-4.0).
    '''
    enrollments = university.get_student_enrollments(student_id)
    total_points = 0.0
    total_credits = 0

    for enrollment in enrollments:
        course = university.get_course(enrollment.course_code)
        if course is not None:
            grade_points = enrollment.get_grade_points()
            credits = course.credits
            total_points += grade_points * credits
            total_credits += credits

    if total_credits == 0:
        return 0.0

    return total_points / total_credits


# Note: Since calculate_simple_gpa is incomplete and requires University and Enrollment objects, 
# these must be mocked/stubbed for valid testing.

class MockEnrollment:
    def __init__(self, course_code, grade_points):
        self.course_code = course_code
        self._grade_points = grade_points
    def get_grade_points(self):
        return self._grade_points

class MockCourse:
    def __init__(self, credits):
        self.credits = credits

class MockUniversity:
    def __init__(self, enrollments, courses):
        # enrollments: dict of student_id -> list of enrollments
        # courses: dict of course_code -> course
        self._enrollments = enrollments
        self._courses = courses
    def get_student_enrollments(self, student_id):
        return self._enrollments.get(student_id, [])
    def get_course(self, course_code):
        return self._courses[course_code]


def calculate_simple_gpa(university, student_id):
    enrollments = university.get_student_enrollments(student_id)
    total_points = 0.0
    total_credits = 0.0
    for enrollment in enrollments:
        course = university.get_course(enrollment.course_code)
        total_points += enrollment.get_grade_points() * course.credits
        total_credits += course.credits
    if total_credits == 0:
        return 0.0
    return total_points / total_credits


# Test Cases

# Test Case 1: Student has no enrollments
enrollments = {}  # no students
courses = {}  # no courses
university = MockUniversity(enrollments, courses)
assert calculate_simple_gpa(university, "student1") == 0.0, "No enrollments - GPA should be 0.0"

# Test Case 2: One enrollment, grade A (4.0), 3 credits
enrollments = {
    "student1": [MockEnrollment("CSE101", 4.0)]
}
courses = {
    "CSE101": MockCourse(3)
}
university = MockUniversity(enrollments, courses)
assert calculate_simple_gpa(university, "student1") == 4.0, "Single enrollment, full marks"

# Test Case 3: Multiple enrollments, mix of grades
enrollments = {
    "student2": [
        MockEnrollment("CSE101", 4.0), # 3 credits
        MockEnrollment("MAT201", 3.0), # 4 credits
        MockEnrollment("PHY111", 2.0)  # 2 credits
    ]
}
courses = {
    "CSE101": MockCourse(3),
    "MAT201": MockCourse(4),
    "PHY111": MockCourse(2)
}
university = MockUniversity(enrollments, courses)
expected_gpa = (
    4.0*3 + 3.0*4 + 2.0*2
) / (3+4+2) # (12+12+4)/9 = 28/9 = 3.111...
assert abs(calculate_simple_gpa(university, "student2") - 3.111) < 0.01, "Multiple enrollments, mix of grades"

# Test Case 4: All failing grades (0.0)
enrollments = {
    "student3": [
        MockEnrollment("CSE101", 0.0),
        MockEnrollment("MAT201", 0.0)
    ]
}
courses = {
    "CSE101": MockCourse(3),
    "MAT201": MockCourse(4)
}
university = MockUniversity(enrollments, courses)
assert calculate_simple_gpa(university, "student3") == 0.0, "All failing grades GPA should be 0.0"

# Test Case 5: Courses with zero credit (should not count toward GPA)
enrollments = {
    "student4": [
        MockEnrollment("CSE101", 4.0),  # 3 credits
        MockEnrollment("LAB100", 4.0)   # 0 credits
    ]
}
courses = {
    "CSE101": MockCourse(3),
    "LAB100": MockCourse(0)
}
university = MockUniversity(enrollments, courses)
assert calculate_simple_gpa(university, "student4") == 4.0, "Course with zero credit ignored"

# Test Case 6: Some enrollments with 0-grade, some high, checking rounding
enrollments = {
    "student5": [
        MockEnrollment("ENG101", 4.0),  # 2 credits
        MockEnrollment("HIS201", 0.0),  # 4 credits
    ]
}
courses = {
    "ENG101": MockCourse(2),
    "HIS201": MockCourse(4)
}
university = MockUniversity(enrollments, courses)
expected_gpa = (4.0*2 + 0.0*4) / (2+4)  # 8/6 = 1.333...
assert abs(calculate_simple_gpa(university, "student5") - 1.333) < 0.01, "Mix of high and low grades"

